-- ONE statement. Run only at the documented step; do not also run master 02.
USE auxiliares;
ALTER TABLE FB_VINCULOS_DECLARADOS
 ADD VERIFICACION_CP_JSON JSON NOT NULL,
 ADD CONSTRAINT FK_71_VINCULO_CP FOREIGN KEY (ID_PERSONA,ID_PERSONA_CP) REFERENCES FB_PERSONAS(ID_PERSONA,ID_PERSONA_CP),
 ADD CONSTRAINT CHK_71_VINCULO_CP CHECK (COALESCE(JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.source'))='institutional' AND JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.padCod'))=CAST(PADCOD AS CHAR),0) AND (ID_PERSONA_CP IS NULL OR COALESCE(JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.personId'))=CAST(ID_PERSONA_CP AS CHAR),0)) AND (CONCOD IS NULL OR (ID_PERSONA_CP IS NOT NULL AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(VERIFICACION_CP_JSON,'$.conCod'))=CAST(CONCOD AS CHAR),0)))),
 ADD CONSTRAINT CHK_71_VINCULO_REL CHECK (RELACION_DECLARADA IS NOT NULL AND CHAR_LENGTH(TRIM(RELACION_DECLARADA))>0),
 ADD CONSTRAINT FK_71_VINCULO_IDENTIDAD FOREIGN KEY (ID_CONSULTA,ID_PERSONA,PADCOD) REFERENCES FB_CIU_CONSULTAS_WEB(ID_CONSULTA,ID_PERSONA,PADCOD);
